// ❌ OLD: A slice of trait objects forces a vtable indirection on
// every compute() call. In a hot loop over millions of items, that
// per-call indirect call (plus no inlining) is measurable overhead.
fn sum_all(items: &[&dyn Computable]) -> f64 {
    items.iter().map(|c| c.compute()).sum() // ❌ OLD: vtable call each
}

// Also, the slice cannot be pre-specialized — every element is a fat
// pointer (2 words each), doubling memory vs a concrete slice.

// trait Computable { fn compute(&self) -> f64; }

// ✅ NEW: A generic over T monomorphizes per concrete type: each
// compute() call is a direct (potentially inlined) call, and the slice
// is a plain contiguous array of the concrete type (no fat pointers).
fn sum_all<T: Computable>(items: &[T]) -> f64 {
    items.iter().map(|c| c.compute()).sum() // ✅ NEW: static dispatch
}

